 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # The scene is an N-by-N array of N-by-N motifs, with one-cell gaps.
    n = round(((h + 1) ** 0.5 - 1) / 2)
    if n * (n + 1) - 1 != h or w != h:
        raise ValueError("expected a square tiled grid")
    step = n + 1
    out = [row[:] for row in grid]

    # Each visible motif is the same N-by-N binary pattern. Use a visible,
    # nonempty tile as the template; color 3 masks one complete tile row/column.
    template = None
    for i in range(n):
        for j in range(n):
            r0, c0 = i * step, j * step
            tile = [grid[r0 + a][c0:c0 + n] for a in range(n)]
            if any(v == 2 for row in tile for v in row):
                template = [[2 if v == 2 else 0 for v in row] for row in tile]
                break
        if template is not None:
            break
    if template is None:
        return [[0 if v == 3 else v for v in row] for row in out]

    # Remove the masking color and gaps, then restore every motif position
    # indicated by the motif itself. The motif's (i,j) cell marks that tile
    # with color 8 when it is a 2.
    out = [[0 if v == 3 else v for v in row] for row in out]
    for i in range(n):
        for j in range(n):
            if template[i][j] != 2:
                continue
            r0, c0 = i * step, j * step
            for a in range(n):
                for b in range(n):
                    if template[a][b] == 2:
                        out[r0 + a][c0 + b] = 2
            out[r0 + i][c0 + j] = 8
    return out

